1	/**
2	 * @module features/tv-dashboard/model/types
3	 *
4	 * Tipos de domínio do Dashboard de Crise (painel TV `/tv`).
5	 * Spec: `.harness/spec/dashboard-tv-crise/spec.md`.
6	 */
7	
8	/**
9	 * Canal de origem do dado de venda de uma unidade.
10	 *
11	 * - `degust-live`: lojas integradas ao POS Degust (flash-vendas ao vivo).
12	 *   O conjunto de lojas vem da tabela `degust_stores` em runtime (hoje:
13	 *   Lago Sul, Águas Claras, BSB Shopping) — nunca hardcoded.
14	 * - `linx-lagged`: lojas no POS Linx sem integração live — usamos o último
15	 *   dia disponível em `historico_vendas` com selo "até DD/MM".
16	 * - `factory`: fábrica (sem venda; card de produção/expedição).
17	 */
18	export type TvSalesChannel = 'degust-live' | 'linx-lagged' | 'factory';
19	
20	/** Estado RAG (red/amber/green) de um card de unidade. */
21	export type TvRagStatus = 'ok' | 'amber' | 'red';
22	
23	/**
24	 * Filtro global de período do painel (v3): hoje / semana corrente
25	 * (segunda→hoje) / mês corrente (dia 1º→hoje). Perdas, compras e seus
26	 * comparativos respeitam o filtro; vendas dos cards são SEMPRE de hoje.
27	 */
28	export type TvPeriod = 'today' | 'week' | 'month';
29	
30	/** Range de dias FECHADO [from, to], ambos YYYY-MM-DD no fuso local. */
31	export interface TvDateRange {
32	  from: string;
33	  to: string;
34	}
35	
36	/** Severidade de um item de estoque crítico (zerado pesa mais). */
37	export type TvCriticalSeverity = 'zerado' | 'abaixo-minimo';
38	
39	/**
40	 * Item de estoque crítico NOMEADO de uma unidade, já ordenável por
41	 * severidade (zerados ⛔ primeiro; depois ⚠ por % faltante).
42	 */
43	export interface TvCriticalItem {
44	  nome: string;
45	  quantidade: number;
46	  minima: number;
47	  severity: TvCriticalSeverity;
48	}
49	
50	/** Linha do feed de movimentações nomeado ("AGORA" / drill-down). */
51	export interface TvRecentMove {
52	  /** Hora local HH:mm derivada de `data_movimentacao` ("—" se ausente). */
53	  hora: string;
54	  /** Timestamp cru ISO da movimentação (ordenar/tooltip), ou null. */
55	  timestamp: string | null;
56	  /** Tipo cru (`entrada` | `saida` | outros valores da tabela). */
57	  tipo: string;
58	  produtoNome: string;
59	  quantidade: number;
60	}
61	
62	/** Perdas agregadas (tabela `perdas`) no período do filtro global. */
63	export interface TvPerdasSummary {
64	  /** R$ somado de `valor_estimado` (linhas sem valor contam como 0). */
65	  valor: number;
66	  /** Número de registros de perda no período. */
67	  itens: number;
68	  /** Delta % vs período anterior equivalente (null sem base positiva). */
69	  deltaPct: number | null;
70	}
71	
72	/** Compras (NFs `notas_fiscais`) agregadas no período do filtro global. */
73	export interface TvComprasSummary {
74	  /** R$ somado de `valor_total` com status válido (≠ erro). */
75	  valor: number;
76	  /** Delta % vs período anterior equivalente (null sem base positiva). */
77	  deltaPct: number | null;
78	}
79	
80	/** Linha detalhada de perda (drill-down por loja). */
81	export interface TvPerdaDetail {
82	  id: number;
83	  produtoNome: string;
84	  quantidade: number;
85	  unidade: string | null;
86	  motivo: string;
87	  /** R$ estimado da perda (0 quando não informado). */
88	  valor: number;
89	  /** Timestamp ISO de `data_identificacao`, ou null. */
90	  data: string | null;
91	}
92	
93	/** Linha detalhada de NF de compra (drill-down por loja). */
94	export interface TvNotaFiscalDetail {
95	  id: number;
96	  numero: string;
97	  fornecedor: string;
98	  valor: number;
99	  /** Data de emissão `data_nota` (YYYY-MM-DD — campo canônico no app). */
100	  dataNota: string;
101	}
102	
103	/** Nível de frescor de um dado-fonte em relação ao intervalo esperado. */
104	export type TvFreshnessLevel = 'fresh' | 'stale' | 'very-stale';
105	
106	/** Severidade de uma exceção exibida na faixa inferior. */
107	export type TvExceptionSeverity = 'red' | 'amber';
108	
109	/** Tipo de exceção exibida na faixa inferior. */
110	export type TvExceptionKind =
111	  | 'stock-out'
112	  | 'stock-low'
113	  | 'no-movement'
114	  | 'stale-data';
115	
116	/** Janela de funcionamento usada no pró-rata da meta (hora local 0-24). */
117	export interface TvBusinessHours {
118	  start: number;
119	  end: number;
120	}
121	
122	/** Snapshot de vendas de uma unidade (live ou defasado). */
123	export interface TvSalesSnapshot {
124	  /** Valor vendido em R$ no dia de referência. */
125	  valor: number;
126	  /** Número de cupons/transações (null quando a fonte não informa). */
127	  cupons: number | null;
128	  /** Ticket médio em R$ (null quando a fonte não informa). */
129	  ticketMedio: number | null;
130	  /** Dia a que o dado se refere (YYYY-MM-DD). Para canal live = hoje. */
131	  dataReferencia: string;
132	  /** true quando o dado é ao vivo (flash-vendas); false = defasado. */
133	  isLive: boolean;
134	  /** Caixa aberto agora (apenas canal live; null quando não se aplica). */
135	  caixaAberto: boolean | null;
136	  /** Timestamp informado pela fonte da última atualização (ISO, ou null). */
137	  atualizadoEm: string | null;
138	}
139	
140	/** Contadores de alerta de estoque de uma unidade (apenas produtos ativos). */
141	export interface TvStockAlertSummary {
142	  /** Itens com quantidade ≤ 0 e mínimo definido (positivo). */
143	  zerados: number;
144	  /** Itens com quantidade entre 0 exclusivo e o mínimo. */
145	  abaixoMinimo: number;
146	}
147	
148	/** Item de estoque em alerta (detalhe usado na faixa de exceções). */
149	export interface TvStockAlertItem {
150	  produtoNome: string;
151	  quantidade: number;
152	  quantidadeMinima: number;
153	  /** true = zerado (vermelho); false = abaixo do mínimo (âmbar). */
154	  zerado: boolean;
155	}
156	
157	/** Heartbeat de movimentações de estoque de uma unidade no dia. */
158	export interface TvMovementSummary {
159	  /** Contagem de movimentações tipo `entrada` hoje. */
160	  entradas: number;
161	  /** Contagem de movimentações tipo `saida` hoje. */
162	  saidas: number;
163	  /** Timestamp ISO da última movimentação ("última bipagem"), ou null. */
164	  ultimaBipagem: string | null;
165	}
166	
167	/** Dados de um card de loja no grid. */
168	export interface TvStoreData {
169	  lojaId: number;
170	  nome: string;
171	  channel: TvSalesChannel;
172	  /** Vendas do dia de referência (null quando não há dado disponível). */
173	  vendas: TvSalesSnapshot | null;
174	  /** Meta do dia da semana de referência (`metas_vendas`), ou null. */
175	  metaDia: number | null;
176	  /**
177	   * % da meta. Canal live = pró-rata da janela de funcionamento;
178	   * canal defasado = % do dia COMPLETO de referência (dia já encerrado).
179	   * null quando não há meta cadastrada ou fora da janela.
180	   */
181	  pctMeta: number | null;
182	  /**
183	   * Delta % vs MESMO DIA da semana anterior — comparativo SECUNDÁRIO desde
184	   * a v3 (o principal é {@link deltaOntem}); a UI decide o que mostrar.
185	   */
186	  deltaSemana: number | null;
187	  /**
188	   * Delta % vs DIA ANTERIOR — comparativo PRINCIPAL (v3).
189	   * Canal live: hoje vs ontem com base PRÓ-RATEADA no mesmo ponto do dia.
190	   * Canal defasado: último dia vs dia anterior a ele (dias completos).
191	   */
192	  deltaOntem: number | null;
193	  estoque: TvStockAlertSummary;
194	  movimentacao: TvMovementSummary;
195	  /** Perdas da loja no PERÍODO do filtro global (+ delta vs anterior). */
196	  perdas: TvPerdasSummary;
197	  /** Compras (NFs) da loja no PERÍODO do filtro global (+ delta). */
198	  compras: TvComprasSummary;
199	  /**
200	   * Estoque crítico NOMEADO, ordenado por severidade (zerados primeiro,
201	   * depois abaixo do mínimo por % faltante). Lista completa — a coluna
202	   * exibe o top 5; o drill-down, tudo.
203	   */
204	  criticalItems: TvCriticalItem[];
205	  /** Mini-feed "AGORA": últimas movimentações de hoje (mais recente 1º). */
206	  recentMoves: TvRecentMove[];
207	  rag: TvRagStatus;
208	  /** Motivos legíveis (pt-BR) que levaram ao estado RAG. */
209	  ragReasons: string[];
210	}
211	
212	/** Produção agregada da fábrica num dia. */
213	export interface TvFactoryProduction {
214	  /** Dia a que a produção se refere (YYYY-MM-DD — último dia com registro). */
215	  dataReferencia: string;
216	  /** Quantidade de produtos distintos produzidos. */
217	  itens: number;
218	  /** Soma das quantidades produzidas. */
219	  totalUnidades: number;
220	}
221	
222	/** Dados do card diferenciado da fábrica. */
223	export interface TvFactoryData {
224	  lojaId: number;
225	  nome: string;
226	  /** Produção do dia (`daily_production` com loja_id NULL), ou null. */
227	  producao: TvFactoryProduction | null;
228	  /** Expedições = movimentações da fábrica hoje (saídas para lojas). */
229	  expedicoes: TvMovementSummary;
230	  estoque: TvStockAlertSummary;
231	  /** Perdas da fábrica no PERÍODO do filtro global (+ delta). */
232	  perdas: TvPerdasSummary;
233	  /** Compras (NFs com loja_id = fábrica) no PERÍODO (+ delta). */
234	  compras: TvComprasSummary;
235	  /** Estoque crítico nomeado da fábrica (mesma ordenação das lojas). */
236	  criticalItems: TvCriticalItem[];
237	  /** Mini-feed "AGORA" da fábrica (últimas movimentações de hoje). */
238	  recentMoves: TvRecentMove[];
239	  rag: TvRagStatus;
240	  ragReasons: string[];
241	}
242	
243	/** Uma linha da faixa de exceções. */
244	export interface TvException {
245	  /** Id estável para keys de render (ex.: `stock-out:4:BROWNIE`). */
246	  id: string;
247	  kind: TvExceptionKind;
248	  severity: TvExceptionSeverity;
249	  lojaId: number | null;
250	  lojaNome: string | null;
251	  /** Mensagem pronta para exibição (pt-BR). */
252	  message: string;
253	  produtoNome?: string;
254	  quantidade?: number;
255	  quantidadeMinima?: number;
256	}
257	
258	/** Faixa de exceções já ordenada (vermelho antes de âmbar) e limitada. */
259	export interface TvExceptionsResult {
260	  items: TvException[];
261	  /** Quantas exceções ficaram de fora do limite (para "+N itens"). */
262	  overflowCount: number;
263	  /** Total de exceções antes do corte. */
264	  totalCount: number;
265	}
266	
267	/** Resumo da rede para o hero. */
268	export interface TvNetworkSummary {
269	  /**
270	   * Vendas de HOJE em R$ — soma apenas das lojas cujo dado é de hoje
271	   * (canal live). Lojas defasadas NÃO entram para não misturar dias.
272	   */
273	  vendasHoje: number;
274	  /** Soma das metas do dia das lojas que contribuem em `vendasHoje`. */
275	  metaDia: number | null;
276	  /** % da meta pró-rata da rede (mesma regra do card de loja live). */
277	  pctMetaProRata: number | null;
278	  /**
279	   * Delta % vs mesmo dia da semana passada (lojas live) — SECUNDÁRIO
280	   * desde a v3 ({@link deltaOntem} é o principal), ou null.
281	   */
282	  deltaSemana: number | null;
283	  /**
284	   * Delta % vs ONTEM (lojas live, base pró-rateada no mesmo ponto do
285	   * dia) — comparativo PRINCIPAL da v3, ou null.
286	   */
287	  deltaOntem: number | null;
288	  /**
289	   * Perdas da REDE no período do filtro (toda a tabela `perdas`,
290	   * inclusive linhas sem loja_id — que não aparecem em nenhuma coluna).
291	   */
292	  perdas: TvPerdasSummary;
293	  /**
294	   * Compras da REDE no período ("gasto até hoje"). NFs com loja_id NULL
295	   * entram SOMENTE aqui (não há coluna para atribuí-las).
296	   */
297	  compras: TvComprasSummary;
298	  /** Total de exceções vermelhas na rede (sem cap de exibição). */
299	  alertasCriticos: number;
300	  /** Quantidade de lojas com venda ao vivo. */
301	  lojasLive: number;
302	  /** Quantidade de lojas com dado defasado. */
303	  lojasDefasadas: number;
304	}
305	
306	/** Frescor de um dado-fonte. */
307	export interface TvSourceFreshness {
308	  /** Última atualização bem-sucedida (ISO), ou null se nunca carregou. */
309	  updatedAt: string | null;
310	  level: TvFreshnessLevel;
311	  /** Intervalo esperado de atualização (ms) usado na classificação. */
312	  expectedIntervalMs: number;
313	}
314	
315	/** Freshness consolidado dos dados exibidos na TV. */
316	export interface TvFreshness {
317	  /** Vendas live (polling 60s na edge `degust-pos-financial`). */
318	  vendasLive: TvSourceFreshness;
319	  /** Estoque/alertas (polling 5min + Realtime). */
320	  estoque: TvSourceFreshness;
321	  /** Momento em que o snapshot foi montado (ISO). */
322	  geradoEm: string;
323	}
