361	// ─────────────────────────────────────────────────────────────────────────────
362	// RAG da loja
363	// ─────────────────────────────────────────────────────────────────────────────
364	
365	/** Entrada da classificação RAG de uma unidade. */
366	export interface StoreRagInput {
367	  /** Itens zerados em alerta (quantidade ≤ 0 com mínimo definido). */
368	  stockOutCount: number;
369	  /** Itens abaixo do mínimo (quantidade entre 0 exclusivo e o mínimo). */
370	  stockLowCount: number;
371	  /** % da meta pró-rata (apenas canal live; null = não avaliar). */
372	  pctMetaProRata: number | null;
373	  /** true quando a unidade tem venda ao vivo (canal Degust). */
374	  isLiveChannel: boolean;
375	  /** Última movimentação de estoque (ISO/Date), ou null se nenhuma hoje. */
376	  lastMovementAt: Date | string | null;
377	  /** Instante da avaliação. */
378	  now: Date;
379	  /** Janela de funcionamento (default lojas; fábrica usa TV_FACTORY_HOURS). */
380	  hours?: TvBusinessHours;
381	  /** Threshold de horas sem movimentação (default lojas 3h; fábrica 2h). */
382	  noMovementThresholdHours?: number;
383	}
384	
385	/**
386	 * Horas sem movimentação consideradas DENTRO da janela de funcionamento.
387	 *
388	 * - Fora da janela (antes de abrir / depois de fechar) retorna null —
389	 *   não faz sentido alertar madrugada sem bipagem.
390	 * - A referência é clampada ao início da janela de hoje: se a última
391	 *   movimentação foi ontem, o "relógio" só começa a contar na abertura.
392	 */
393	export function hoursWithoutMovementInWindow(
394	  lastMovementAt: Date | string | null,
395	  now: Date,
396	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
397	): number | null {
398	  const fraction = businessDayFraction(now, hours);
399	  if (fraction <= 0 || fraction >= 1) return null;
400	  const windowStart = new Date(now);
401	  windowStart.setHours(hours.start, 0, 0, 0);
402	  const last = lastMovementAt
403	    ? new Date(lastMovementAt).getTime()
404	    : Number.NEGATIVE_INFINITY;
405	  const ref = Math.max(last, windowStart.getTime());
406	  return (now.getTime() - ref) / 3_600_000;
407	}
408	
409	/**
410	 * Classificação RAG de uma unidade (management-by-exception).
411	 *
412	 * Regras (design.md §1.6, ordem de precedência):
413	 * - VERMELHO: SOMENTE ruptura — item zerado em alerta (`stockOutCount > 0`).
414	 *   Venda fraca NUNCA derruba o card pra vermelho (era falso-positivo de
415	 *   manhã, quando o pró-rata ainda é instável).
416	 * - ÂMBAR: itens abaixo do mínimo (`stockLowCount > 0`) OU unidade sem
417	 *   movimentação há mais que o threshold dentro da janela OU venda live com
418	 *   ratio pró-rata abaixo de {@link LIVE_SALES_AMBER_THRESHOLD_PCT}% —
419	 *   esta última SOMENTE a partir de {@link LIVE_SALES_AMBER_FROM_HOUR}h,
420	 *   em canal live e com meta cadastrada (pct != null).
421	 * - OK: nenhum desvio — tela calma, sem cor.
422	 */
423	export function classifyStoreRag(input: StoreRagInput): {
424	  status: TvRagStatus;
425	  reasons: string[];
426	} {
427	  const hours = input.hours ?? TV_BUSINESS_HOURS;
428	  const noMovementThreshold =
429	    input.noMovementThresholdHours ?? NO_MOVEMENT_THRESHOLD_HOURS;
430	  const reasons: string[] = [];
431	
432	  // ── Vermelho: só ruptura (item zerado em alerta) ──
433	  if (input.stockOutCount > 0) {
434	    reasons.push(
435	      `${input.stockOutCount} ${input.stockOutCount === 1 ? 'item zerado' : 'itens zerados'} em alerta`,
436	    );
437	    return { status: 'red', reasons };
438	  }
439	
440	  // ── Âmbar ──
441	  if (input.stockLowCount > 0) {
442	    reasons.push(
443	      `${input.stockLowCount} ${input.stockLowCount === 1 ? 'item abaixo' : 'itens abaixo'} do mínimo`,
444	    );
445	  }
446	  const gapHours = hoursWithoutMovementInWindow(
447	    input.lastMovementAt,
448	    input.now,
449	    hours,
450	  );
451	  if (gapHours !== null && gapHours > noMovementThreshold) {
452	    reasons.push(`sem movimentação há ${Math.floor(gapHours)}h`);
453	  }
454	  if (
455	    input.isLiveChannel &&
456	    input.pctMetaProRata !== null &&
457	    input.pctMetaProRata < LIVE_SALES_AMBER_THRESHOLD_PCT &&
458	    input.now.getHours() >= LIVE_SALES_AMBER_FROM_HOUR
459	  ) {
460	    reasons.push(
461	      `venda ao vivo em ${Math.round(input.pctMetaProRata)}% do esperado pró-rata`,
462	    );
463	  }
464	  if (reasons.length > 0) return { status: 'amber', reasons };
465	
466	  return { status: 'ok', reasons: [] };
467	}
