509	// ─────────────────────────────────────────────────────────────────────────────
510	// Formatação compacta de moeda (tipografia de TV: "R$ 12,4k")
511	// ─────────────────────────────────────────────────────────────────────────────
512	
513	function trimOneDecimal(v: number): string {
514	  const rounded = Math.round(v * 10) / 10;
515	  return rounded.toLocaleString('pt-BR', {
516	    minimumFractionDigits: 0,
517	    maximumFractionDigits: 1,
518	  });
519	}
520	
521	/**
522	 * Formata um valor em BRL compacto para leitura a 3-5 metros:
523	 * 950 → "R$ 950" · 12.400 → "R$ 12,4k" · 1.250.000 → "R$ 1,3M".
524	 * Valores negativos preservam o sinal ("-R$ 1,2k").
525	 */
526	export function formatCompactBRL(value: number): string {
527	  const sign = value < 0 ? '-' : '';
528	  const abs = Math.abs(value);
529	  // Bump pra M quando o arredondamento em k chegaria a 1000k
530	  if (abs >= 1_000_000 || (abs >= 1_000 && Math.round(abs / 100) >= 10_000)) {
531	    return `${sign}R$ ${trimOneDecimal(abs / 1_000_000)}M`;
532	  }
533	  if (abs >= 1_000) {
534	    return `${sign}R$ ${trimOneDecimal(abs / 1_000)}k`;
535	  }
536	  return `${sign}R$ ${Math.round(abs).toLocaleString('pt-BR')}`;
537	}
