680	/**
681	 * Normaliza um valor de `produtos_master.setor` para comparação: trim,
682	 * minúsculas e remoção de acentos (NFD). O banco tem caixa/acentuação
683	 * inconsistentes no MESMO setor (ex.: "CÂMARA FRIA" e "Câmara Fria") —
684	 * toda comparação de setor DEVE passar por aqui.
685	 */
686	export function normalizeSetor(value: string | null | undefined): string {
687	  return (value ?? '')
688	    .normalize('NFD')
689	    .replace(/\p{M}/gu, '')
690	    .trim()
691	    .toLowerCase();
692	}
693	
694	/**
695	 * true quando o setor é o {@link TV_ALERT_SETOR} (igualdade EXATA após
696	 * {@link normalizeSetor} — nunca prefixo: "PRODUTOS DE LIMPEZA" NÃO conta).
697	 */
698	export function isTvAlertSetor(setor: string | null | undefined): boolean {
699	  return normalizeSetor(setor) === normalizeSetor(TV_ALERT_SETOR);
700	}
