702	/** Linha mínima de `estoque` (com nome do produto ativo já joinado). */
703	export interface StockRow {
704	  loja_id: number | null;
705	  quantidade_atual: number | null;
706	  quantidade_minima: number | null;
707	  produtoNome: string;
708	  /** `produtos_master.setor` cru (caixa/acentos inconsistentes no banco). */
709	  setor: string | null;
710	}
