797	/**
798	 * Corrige o `loja_id` das linhas de flash-vendas.
799	 *
800	 * LANDMINE conhecida: a edge function `degust-pos-financial` (deployada)
801	 * só mapeia os códigos Degust 1→4 e 2→5; códigos não mapeados passam CRUS
802	 * (ex.: BSB Shopping = código Degust 3 chega como `loja_id: 3`, colidindo
803	 * com Asa Norte). Aqui remapeamos usando a tabela `degust_stores`
804	 * (degust_loja_codigo → loja_id), que é a fonte de verdade em runtime.
805	 *
806	 * - Linha cujo loja_id já é uma loja Degust conhecida → mantém.
807	 * - Linha cujo loja_id corresponde a um código Degust → remapeia.
808	 * - Caso contrário → descarta (não corromper outra loja).
809	 */
810	export function remapFlashLojaIds(
811	  rows: FlashRow[],
812	  degustCodeToLoja: ReadonlyMap<number, number>,
813	  knownDegustLojaIds: ReadonlySet<number>,
814	): FlashRow[] {
815	  const out: FlashRow[] = [];
816	  for (const row of rows) {
817	    if (knownDegustLojaIds.has(row.loja_id)) {
818	      out.push(row);
819	      continue;
820	    }
821	    const mapped = degustCodeToLoja.get(row.loja_id);
822	    if (mapped != null) {
823	      out.push({ ...row, loja_id: mapped });
824	    }
825	    // não mapeável → descartado de propósito (ver TSDoc)
826	  }
827	  return out;
828	}
