830	/**
831	 * Converte os itens de alerta de uma unidade em estoque crítico NOMEADO,
832	 * ordenado por severidade: zerados (⛔) primeiro, depois abaixo do mínimo
833	 * (⚠) por % FALTANTE decrescente ((minima − quantidade) / minima); empate
834	 * por nome (estável). Dentro dos zerados, quantidade mais negativa primeiro
835	 * (mesma fração). A coluna exibe os {@link TV_CRITICAL_TOP_N} primeiros;
836	 * o drill-down, a lista completa.
837	 */
838	export function sortCriticalItems(items: TvStockAlertItem[]): TvCriticalItem[] {
839	  const missingFraction = (c: TvCriticalItem): number =>
840	    c.minima > 0 ? (c.minima - c.quantidade) / c.minima : 0;
841	  return items
842	    .map<TvCriticalItem>((i) => ({
843	      nome: i.produtoNome,
844	      quantidade: i.quantidade,
845	      minima: i.quantidadeMinima,
846	      severity: i.zerado ? 'zerado' : 'abaixo-minimo',
847	    }))
848	    .sort((a, b) => {
849	      if (a.severity !== b.severity) return a.severity === 'zerado' ? -1 : 1;
850	      const diff = missingFraction(b) - missingFraction(a);
851	      if (diff !== 0) return diff;
852	      return a.nome.localeCompare(b.nome, 'pt-BR');
853	    });
854	}
