875	/**
876	 * Agrega perdas do período: R$ (soma de `valor_estimado`, nulls contam 0 —
877	 * a perda EXISTE mesmo sem valor estimado e entra na contagem de itens) e
878	 * nº de registros, por loja e total da rede. Linhas sem loja_id entram
879	 * SOMENTE no total (não há coluna para atribuí-las).
880	 */
881	export function aggregatePerdas(rows: PerdaAggRow[]): PerdasByLoja {
882	  const byLoja = new Map<number, PerdasAggregate>();
883	  const total: PerdasAggregate = { valor: 0, itens: 0 };
884	  for (const row of rows) {
885	    const valor = row.valor_estimado ?? 0;
886	    total.valor += valor;
887	    total.itens += 1;
888	    if (row.loja_id == null) continue;
889	    let agg = byLoja.get(row.loja_id);
890	    if (!agg) {
891	      agg = { valor: 0, itens: 0 };
892	      byLoja.set(row.loja_id, agg);
893	    }
894	    agg.valor += valor;
895	    agg.itens += 1;
896	  }
897	  return { byLoja, total };
898	}
