950	/**
951	 * Agrupa o feed (já ordenado DESC por `data_movimentacao` na query) por
952	 * loja, mantendo as `perStore` primeiras linhas de cada uma (mini-feed
953	 * "AGORA"). Linhas sem loja são ignoradas. NÃO reordena — confia na
954	 * ordenação da query (única fonte do "mais recente primeiro").
955	 */
956	export function buildRecentMoves(
957	  rows: MovementFeedRow[],
958	  perStore: number = TV_MINI_FEED_SIZE,
959	): Map<number, TvRecentMove[]> {
960	  const out = new Map<number, TvRecentMove[]>();
961	  for (const row of rows) {
962	    if (row.loja_id == null) continue;
963	    let list = out.get(row.loja_id);
964	    if (!list) {
965	      list = [];
966	      out.set(row.loja_id, list);
967	    }
968	    if (list.length >= perStore) continue;
969	    list.push(mapFeedRow(row));
970	  }
971	  return out;
972	}
