1	/**
2	 * @module features/tv-dashboard/model/useMinuteClock
3	 *
4	 * Tick de minuto do Painel TV, alinhado à virada do minuto. Duplo papel:
5	 * - relógio do hero (design.md §3 zona 4 — sem segundos);
6	 * - "now" que AVANÇA dentro do `useTvDashboardData`, para staleness/RAG
7	 *   escalarem mesmo em outage total (nenhuma query devolvendo dado novo).
8	 */
9	
10	import { useEffect, useState } from 'react';
11	
12	/** Retorna o instante atual, re-renderizando uma vez por minuto. */
13	export function useMinuteClock(): Date {
14	  const [now, setNow] = useState(() => new Date());
15	
16	  useEffect(() => {
17	    let timer: number;
18	    const schedule = () => {
19	      // +80ms de folga pra garantir que já virou o minuto
20	      timer = window.setTimeout(() => {
21	        setNow(new Date());
22	        schedule();
23	      }, 60_000 - (Date.now() % 60_000) + 80);
24	    };
25	    schedule();
26	    return () => window.clearTimeout(timer);
27	  }, []);
28	
29	  return now;
30	}
