1	/**
2	 * @module features/tv-dashboard/model/useTvRealtime
3	 *
4	 * Assina canais Supabase Realtime nas tabelas `movimentacoes`, `estoque`,
5	 * `alertas_estoque` e `perdas` (mesmo padrão de
6	 * `features/dashboard/useRealtimeUpdates`) e invalida as query keys do
7	 * painel TV para refletir mudanças antes do próximo ciclo de polling.
8	 *
9	 * As invalidações são debounced (janela de 2s) para não estourar refetches
10	 * durante rajadas de bipagem (conferência de expedição gera dezenas de
11	 * INSERTs em sequência).
12	 */
13	
14	import { useEffect, useRef } from 'react';
15	import { useQueryClient } from '@tanstack/react-query';
16	import { supabase } from '@/integrations/supabase/client';
17	import { tvDashboardKeys } from './useTvDashboardData';
18	
19	/** Janela de debounce das invalidações disparadas pelo Realtime (ms). */
20	const REALTIME_DEBOUNCE_MS = 2_000;
21	
22	/**
23	 * Subscreve `postgres_changes` em movimentações/estoque/alertas/perdas e
24	 * invalida as queries relevantes do painel TV:
25	 * - `movimentacoes` → heartbeat + feed nomeado "AGORA" (+ drill-down);
26	 * - `estoque` / `alertas_estoque` → alertas de estoque (faixa de exceções);
27	 * - `perdas` → agregados de perdas de TODOS os períodos (+ drill-down).
28	 *
29	 * Remove os canais e cancela timers pendentes ao desmontar.
30	 */
31	export function useTvRealtime(): void {
32	  const queryClient = useQueryClient();
33	  // Timers por grupo de invalidação (debounce independente)
34	  const movementTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
35	  const stockTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
36	  const perdasTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
37	
38	  useEffect(() => {
39	    const invalidateMovements = () => {
40	      if (movementTimer.current) return; // já agendado nesta janela
41	      movementTimer.current = setTimeout(() => {
42	        movementTimer.current = null;
43	        queryClient.invalidateQueries({ queryKey: tvDashboardKeys.movements() });
44	        queryClient.invalidateQueries({ queryKey: tvDashboardKeys.movementFeed() });
45	        // Drill-down aberto também mostra feed/contagens — prefixo invalida
46	        // todas as lojas/ranges de uma vez (refetch só das queries ativas).
47	        queryClient.invalidateQueries({
48	          queryKey: tvDashboardKeys.storeDetailRoot(),
49	        });
50	      }, REALTIME_DEBOUNCE_MS);
51	    };
52	
53	    const invalidateStock = () => {
54	      if (stockTimer.current) return;
55	      stockTimer.current = setTimeout(() => {
56	        stockTimer.current = null;
57	        queryClient.invalidateQueries({ queryKey: tvDashboardKeys.stock() });
58	      }, REALTIME_DEBOUNCE_MS);
59	    };
60	
61	    const invalidatePerdas = () => {
62	      if (perdasTimer.current) return;
63	      perdasTimer.current = setTimeout(() => {
64	        perdasTimer.current = null;
65	        // Prefixo cobre todos os períodos (today/week/month) de uma vez
66	        queryClient.invalidateQueries({ queryKey: tvDashboardKeys.perdasRoot() });
67	        queryClient.invalidateQueries({
68	          queryKey: tvDashboardKeys.storeDetailRoot(),
69	        });
70	      }, REALTIME_DEBOUNCE_MS);
71	    };
72	
73	    const movementsChannel = supabase
74	      .channel('tv-movements-changes')
75	      .on(
76	        'postgres_changes',
77	        { event: '*', schema: 'public', table: 'movimentacoes' },
78	        invalidateMovements,
79	      )
80	      .subscribe();
81	
82	    const stockChannel = supabase
83	      .channel('tv-stock-changes')
84	      .on(
85	        'postgres_changes',
86	        { event: '*', schema: 'public', table: 'estoque' },
87	        invalidateStock,
88	      )
89	      .subscribe();
90	
91	    const alertsChannel = supabase
92	      .channel('tv-alerts-changes')
93	      .on(
94	        'postgres_changes',
95	        { event: '*', schema: 'public', table: 'alertas_estoque' },
96	        invalidateStock,
97	      )
98	      .subscribe();
99	
100	    const perdasChannel = supabase
101	      .channel('tv-perdas-changes')
102	      .on(
103	        'postgres_changes',
104	        { event: '*', schema: 'public', table: 'perdas' },
105	        invalidatePerdas,
106	      )
107	      .subscribe();
108	
109	    return () => {
110	      if (movementTimer.current) clearTimeout(movementTimer.current);
111	      if (stockTimer.current) clearTimeout(stockTimer.current);
112	      if (perdasTimer.current) clearTimeout(perdasTimer.current);
113	      movementTimer.current = null;
114	      stockTimer.current = null;
115	      perdasTimer.current = null;
116	      supabase.removeChannel(movementsChannel);
117	      supabase.removeChannel(stockChannel);
118	      supabase.removeChannel(alertsChannel);
119	      supabase.removeChannel(perdasChannel);
120	    };
121	  }, [queryClient]);
122	}
