275	  const previous = previousRangeSameDuration(range);
276	  const isDegust = ctx.degustLojaIds.has(lojaId);
277	
278	  const [
279	    vendasCur,
280	    vendasPrev,
281	    perdasCur,
282	    perdasPrevValor,
283	    notasCur,
284	    notasPrevValor,
285	    movsCur,
286	    movsPrev,
287	    feed,
288	  ] = await Promise.all([
289	    loadVendasRange(isDegust, lojaId, range),
290	    loadVendasRange(isDegust, lojaId, previous),
291	    loadPerdasDetail(lojaId, range),
292	    loadPerdasAggregate(lojaId, previous),
293	    loadNotasDetail(lojaId, range),
294	    loadNotasAggregate(lojaId, previous),
295	    loadMovementCounts(lojaId, range),
296	    loadMovementCounts(lojaId, previous),
297	    loadFeed(lojaId, range),
298	  ]);
299	
300	  return {
301	    vendas: { valor: vendasCur, previous: vendasPrev },
302	    perdas: {
303	      valor: perdasCur.valor,
304	      itens: perdasCur.itens,
305	      previousValor: perdasPrevValor,
306	    },
307	    compras: { valor: notasCur.valor, previousValor: notasPrevValor },
308	    movimentos: { current: movsCur, previous: movsPrev },
309	    perdasList: perdasCur.list,
310	    notasList: notasCur.list,
311	    feed,
312	  };
313	}
